<?php require_once 'bootstrap.php';$u=require_login();$myClub=user_club_sic($u['sic_id']);if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['create_proposal']??'')==='1'){csrf_check();$title=trim($_POST['title']??'');$body=trim($_POST['body']??'');$scopeChoice=$_POST['scope']??'CLUB';$scope=$scopeChoice==='GLOBAL'&&dao_can_create_global($u['sic_id'])?null:$myClub;if(!$scope&&$scopeChoice!=='GLOBAL'&&!dao_can_create_global($u['sic_id']))throw new RuntimeException('Serve una membership Club attiva per creare una proposta.');if($title){db()->prepare('INSERT INTO dao_proposals(sic_id,scope_sic_id,title,body,proposal_type,voting_method,status,created_by_sic_id,opens_at,closes_at) VALUES(?,?,?,?,?,? ,"VOTING",?,CURRENT_TIMESTAMP,datetime("now","+7 days"))')->execute([sic_id(),$scope,$title,$body,$_POST['proposal_type']??'GENERAL','ONE_MEMBER_ONE_VOTE',$u['sic_id']]);audit($u['sic_id'],'DAO_PROPOSAL_CREATE',null,['scope'=>$scope]);}}$all=db()->query("SELECT p.*,SUM(CASE WHEN v.choice='YES' THEN v.weight ELSE 0 END) yes_votes,SUM(CASE WHEN v.choice='NO' THEN v.weight ELSE 0 END) no_votes,SUM(CASE WHEN v.choice='ABSTAIN' THEN v.weight ELSE 0 END) abstain_votes FROM dao_proposals p LEFT JOIN dao_proposal_votes v ON v.proposal_sic_id=p.sic_id GROUP BY p.sic_id ORDER BY p.created_at DESC")->fetchAll();$ps=array_values(array_filter($all,fn($p)=>dao_scope_access($u['sic_id'],$p['scope_sic_id']??null)));$pageTitle='DAO Forum';require '_header.php';?><section class="section-head"><div><span class="eyebrow">Governance federata</span><h1>DAO Forum</h1><p>Vedi solo gli scope DAO consentiti dal tuo Club e dai tuoi ruoli.</p></div></section><section class="card"><h2>Nuova proposta</h2><form method="post" class="stack"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><input type="hidden" name="create_proposal" value="1"><label>Titolo<input name="title" required></label><label>Descrizione<textarea name="body" rows="4"></textarea></label><label>Tipo<select name="proposal_type"><option>GENERAL</option><option>CLUB</option><option>EVENT</option><option>SOCIAL_PROJECT</option><option>TRAINING</option></select></label><label>Ambito<select name="scope"><option value="CLUB">Il mio Club</option><?php if(dao_can_create_global($u['sic_id'])):?><option value="GLOBAL">Globale</option><?php endif;?></select></label><button class="btn primary">Pubblica proposta</button></form></section><div class="topic-list"><?php foreach($ps as $p):?><article class="topic"><div><span class="pill"><?=h($p['scope_sic_id']?'CLUB/SCOPE':'GLOBAL')?></span><span class="pill"><?=h($p['status'])?></span><span class="pill vote"><?=h($p['voting_method'])?></span></div><h3><?=h($p['title'])?></h3><p><?=h($p['body'])?></p><p>👍 <?=h((string)($p['yes_votes']??0))?> · 👎 <?=h((string)($p['no_votes']??0))?> · ◯ <?=h((string)($p['abstain_votes']??0))?></p><form method="post" action="action.php" class="vote-row"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="dao_vote"><input type="hidden" name="proposal_sic_id" value="<?=h($p['sic_id'])?>"><input type="hidden" name="return" value="dao.php"><button name="choice" value="YES" class="btn small">Sì</button><button name="choice" value="NO" class="btn small">No</button><button name="choice" value="ABSTAIN" class="btn small">Mi astengo</button></form></article><?php endforeach;?></div><?php require '_footer.php';?>